import{_ as o,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Backup em arquivo","description":"","frontmatter":{"title":"Backup em arquivo","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/geral/backup-arquivo"}]]},"headers":[],"relativePath":"geral/backup-arquivo.md","filePath":"geral/backup-arquivo.md"}'),i={name:"geral/backup-arquivo.md"};function t(d,a,l,n,u,p){return e(),r("div",null,a[0]||(a[0]=[s('<h1 id="backup-em-arquivo" tabindex="-1">Backup em arquivo <a class="header-anchor" href="#backup-em-arquivo" aria-label="Permalink to &quot;Backup em arquivo&quot;">​</a></h1><p>Salva todas as configurações e dados do eploc num arquivo JSON, para guardar, levar para outro computador ou restaurar depois. Também permite exportar só algumas bases de dados para compartilhar com colegas.</p><h2 id="onde-fica" tabindex="-1">Onde fica <a class="header-anchor" href="#onde-fica" aria-label="Permalink to &quot;Onde fica&quot;">​</a></h2><p>Configurações → aba <strong>Ajustes gerais e Backup</strong> → cards <strong>Importar e exportar</strong> e <strong>Exportar bases de dados</strong>.</p><h2 id="exportar-tudo" tabindex="-1">Exportar tudo <a class="header-anchor" href="#exportar-tudo" aria-label="Permalink to &quot;Exportar tudo&quot;">​</a></h2><ol><li>Clique em <strong>Exportar JSON</strong>.</li><li>Guarde o arquivo baixado.</li></ol><p>O arquivo inclui:</p><ul><li>os interruptores e opções de todas as funcionalidades e os ajustes gerais;</li><li>os dados salvos: histórico de e-mails, modelos de mensagem, destaques de trecho e paleta de cores, processos monitorados e colunas excluídas do monitoramento, pastas das listas de preferências, leis de regência das RPVs por devedor;</li><li>preferências lembradas pelas funcionalidades (ações favoritas e ocultas, perfil favorito do login, seções do Painel do Servidor, preferências e colunas fixadas, avisos rotineiros e ocultos, dicas já fechadas, opções favoritas dos campos de seleção, rótulos aprendidos do CPHA etc.).</li></ul><h2 id="exportar-so-algumas-bases" tabindex="-1">Exportar só algumas bases <a class="header-anchor" href="#exportar-so-algumas-bases" aria-label="Permalink to &quot;Exportar só algumas bases&quot;">​</a></h2><ol><li>No card <strong>Exportar bases de dados</strong>, marque o que quer exportar: <strong>E-mails</strong>, <strong>Modelos de mensagem</strong>, <strong>Destaques</strong>, <strong>Processos monitorados</strong>, <strong>Pastas das listas de preferências do processo</strong> e/ou <strong>Leis de regência das RPVs por devedor</strong>.</li><li>Clique em <strong>Exportar selecionadas</strong>.</li></ol><p>Útil para passar seus modelos ou contatos a outra pessoa sem levar junto as suas preferências.</p><h2 id="importar" tabindex="-1">Importar <a class="header-anchor" href="#importar" aria-label="Permalink to &quot;Importar&quot;">​</a></h2><ol><li>Clique em <strong>Importar JSON</strong> e escolha o arquivo. Também é possível arrastar o arquivo para qualquer lugar da página de configurações ou para o <a href="./popup">popup</a>.</li><li>Na revisão da importação, desmarque o checkbox à esquerda de cada item que não quer importar. Para cada base, você pode <strong>mesclar</strong> com o que já existe (padrão, nunca apaga nada) ou <strong>substituir</strong> pelo conteúdo do arquivo.</li><li>Nas funcionalidades (e em <strong>Extensão ativada</strong>), o interruptor à direita mostra se ela vem ligada ou desligada no arquivo. Mude-o para importar as configurações já no estado que preferir. Quando o estado escolhido é diferente do atual, a linha mostra, por exemplo, &quot;hoje: desligado&quot;.</li><li>Quando um item existe dos dois lados com conteúdo diferente, escolha entre <strong>Manter o que está salvo (recomendado)</strong> e <strong>Usar a versão do backup</strong>.</li><li>Clique em <strong>Importar selecionados</strong>.</li></ol><p>Se o arquivo for idêntico ao que já está salvo, o eploc avisa e não há nada a importar.</p><h2 id="o-que-nao-vai-para-o-arquivo" tabindex="-1">O que não vai para o arquivo <a class="header-anchor" href="#o-que-nao-vai-para-o-arquivo" aria-label="Permalink to &quot;O que não vai para o arquivo&quot;">​</a></h2><ul><li>O valor anterior das colunas do <a href="./../funcionalidades/eproc-monitor-relatorio">Monitor de Relatórios</a>, que fica cifrado só no computador onde foi guardado.</li><li>Dados temporários ou que dependem deste computador: histórico de alertas, nomes de usuários memorizados, dados de processos lidos para os modelos de mensagem, descrições de eventos migrados, configuração de múltiplos monitores, posição dos painéis.</li></ul><h2 id="cuidados" tabindex="-1">Cuidados <a class="header-anchor" href="#cuidados" aria-label="Permalink to &quot;Cuidados&quot;">​</a></h2><ul><li>O arquivo contém dados que você salvou no eploc, como endereços de e-mail de contatos e textos de modelos. Guarde-o como guardaria qualquer documento de trabalho.</li></ul>',18)]))}const g=o(i,[["render",t]]);export{m as __pageData,g as default};
